const board=$('#wallBoard'),wallBox=$('#wallBox'),notes=[];let seed=11;const rnd=()=>{seed=(seed*9301+49297)%233280;return seed/233280};
TH.forEach(t=>{const h=document.createElement('span');h.className='th-head';h.textContent=t[1];h.dataset.t=t[0];h.onclick=()=>filt(t[0]);board.appendChild(h);
  t[3].forEach(x=>{const n=document.createElement('div');n.className='wn'+(x.startsWith('“')?' q':'');n.style.setProperty('--bg',t[2]);n.textContent=x;n.dataset.t=t[0];n.dataset.r=(rnd()*12-6).toFixed(1);n.dataset.fx=rnd();n.dataset.fy=rnd();board.appendChild(n);notes.push(n)})});
let clustered=false;
function layWall(){const W=board.clientWidth,narrow=W<640,cols=narrow?2:5,gap=12,px=16;const nw=Math.min(250,(W-px*2-gap*(cols-1))/cols);board.style.setProperty('--nw',nw+'px');
  if(!clustered){const H=narrow?720:520;board.style.setProperty('--wh',H+'px');notes.forEach(n=>{n.style.transform='translate('+(px+(+n.dataset.fx)*(W-nw-px*2))+'px,'+(16+(+n.dataset.fy)*(H-110))+'px) rotate('+n.dataset.r+'deg)'});return}
  const colY=new Array(cols).fill(16);TH.forEach(t=>{const c=colY.indexOf(Math.min(...colY)),x=px+c*(nw+gap);let y=colY[c];$('.th-head[data-t="'+t[0]+'"]',board).style.transform='translate('+x+'px,'+y+'px)';y+=30;
    notes.filter(n=>n.dataset.t===t[0]).forEach((n,k)=>{n.style.transitionDelay=RM?'0s':(k*60)+'ms';n.style.transform='translate('+x+'px,'+y+'px) rotate(0deg)';y+=n.offsetHeight+8});colY[c]=y+18});
  board.style.setProperty('--wh',Math.max(...colY)+10+'px');wallBox.classList.add('clustered')}
let curTheme=null;
function filt(k){curTheme=curTheme===k?null:k;STATS.theme=curTheme?TH.find(t=>t[0]===k)[1]:STATS.theme;$$('#themes button,#convThemes button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.t===curTheme));wallBox.classList.toggle('dim',!!curTheme);notes.forEach(n=>n.classList.toggle('lit',n.dataset.t===curTheme));$$('#convSvg path').forEach(p=>p.classList.toggle('on',p.dataset.t===curTheme))}
TH.forEach(t=>{const b=document.createElement('button');b.className='kit-chip';b.dataset.t=t[0];b.textContent=t[1];b.setAttribute('aria-pressed','false');b.onclick=()=>filt(t[0]);$('#themes').appendChild(b)});
layWall();addEventListener('resize',layWall);
onceVisible(wallBox,()=>setTimeout(()=>{clustered=true;layWall()},RM?0:500),.3);
$('#convThemes').innerHTML=TH.map((t,i)=>'<button class="cth" data-t="'+t[0]+'" aria-pressed="false" style="--i:'+i+';--bg:'+t[2]+'"><span class="k"><span>Theme '+pad(i+1)+'</span><span>'+t[3].length+' notes</span></span><b>'+t[1]+'</b><p>'+t[4]+'</p></button>').join('');
$$('#convThemes .cth').forEach(b=>b.onclick=()=>{filt(b.dataset.t);if(curTheme)wallBox.scrollIntoView({behavior:RM?'auto':'smooth',block:'center'})});
$('#convSvg').innerHTML=TH.map((t,i)=>{const x=100+i*200;return '<path data-t="'+t[0]+'" pathLength="1" vector-effect="non-scaling-stroke" d="M'+x+' 0 C '+x+' 70, 500 50, 500 118"/>'}).join('')+'<circle cx="500" cy="118" r="5" vector-effect="non-scaling-stroke"/>';
