  [[0,'e',191,'-2s',' l'],[1,'e',191,'-7s',' m'],[2,'w',215,'-4s',' m'],[3,'w',215,'-9.5s',''],[4,'e',191,'-10s',''],[5,'w',215,'-1s','']].forEach(r=>{s+='<g class="rc '+r[1]+r[4]+'" style="animation-delay:'+r[3]+'">'+CAR(0,r[2],46,r[1]==='w'?180:0,CARC[(r[0]*3+2)%CARC.length])+'</g>'});
