 list:'<div class="wfx"><span class="ttl">Available slots</span><div class="r"><span>A05</span><span>A12</span><span>A13</span><span>A25</span></div><div class="r"><span>A26</span><span>—</span><span>—</span><span>—</span></div><div class="b">Continue</div></div>',
